
/* ===== V44: COMISSÕES, ACERTOS, VALES, GORJETAS E PAGAMENTO DIRETO ===== */
let proAreaTab='cadastro';
let commissionFrom=localDateISO().slice(0,7)+'-01',commissionTo=localDateISO(),commissionUnit='all',commissionPro='all';
if(!Array.isArray(db.commissionSettlements))db.commissionSettlements=[];
if(!db.commissionSettings)db.commissionSettings={discountsReduceBase:true,directPaymentReducesSettlement:true,comboAllocation:'proportional'};
function commissionEnsureDateDefaults(){let today=(typeof financeToday!=='undefined'?financeToday:localDateISO());let month=today.slice(0,7);if(!commissionFrom||!commissionTo){commissionFrom=month+'-01';commissionTo=today}if(commissionFrom>commissionTo)commissionTo=commissionFrom}
function proSubnav(){return `<div class="pro-subnav"><button class="${proAreaTab==='cadastro'?'active':''}" onclick="proAreaTab='cadastro';renderPros()">Cadastro</button><button class="${proAreaTab==='commissions'?'active':''}" onclick="proAreaTab='commissions';renderPros()">Comissões & Acertos</button></div>`}
const _renderProsV44Base=renderPros;
renderPros=function(){if(proAreaTab==='commissions'){subbar.innerHTML=proSubnav();return renderCommissionCenter()}let r=_renderProsV44Base();subbar.innerHTML=proSubnav();return r}

function commissionProIdFromName(name=''){let n=normName(name);return db.pros.find(p=>normName(p.name)===n||normName(p.publicName||'')===n)?.id||''}
function commissionServiceIdFromName(name=''){let n=normName(name);return db.services.find(s=>normName(s.name)===n)?.id||''}
function commissionPercent(serviceId,proId){let s=db.services.find(x=>x.id===serviceId);let r=s?.proRules?.[proId];let v=r?.commission;return v===null||v===undefined||v===''?0:Math.max(0,Number(v)||0)}
function commissionCommandServiceLines(c){
  try{if(typeof normalizeCommand==='function')normalizeCommand(c)}catch(e){}
  let rows=(c.lines||[]).filter(l=>l.type==='service').map((l,i)=>({
    source:'command',key:`svc:${c.id}:${l.id||i}`,commandId:c.id,date:c.date,unitId:c.unitId,clientId:c.clientId,
    serviceId:l.serviceId||commissionServiceIdFromName(l.name),serviceName:l.name||db.services.find(s=>s.id===l.serviceId)?.name||'Serviço',
    professionalId:l.professionalId||commissionProIdFromName(l.professionalName),professionalName:l.professionalName||'',
    gross:Math.max(0,Number(l.unitPrice||0)*Math.max(1,Number(l.qty||1))),manualDiscount:Math.max(0,Number(l.discount||0)),lineId:l.id||String(i)
  }));
  if(rows.length)return rows;
  let aps=(db.clientAppointments||[]).filter(a=>a.clientId===c.clientId&&a.date===c.date&&a.status==='Concluído');
  if(!aps.length&&Array.isArray(c.items))aps=(c.items||[]).map((name,i)=>({id:`fallback${i}`,service:name,professional:'',value:(Number(c.total||0)/(c.items.length||1))}));
  return aps.map((a,i)=>({source:'appointment',key:`svc:${c.id}:appt:${a.id||i}`,commandId:c.id,date:c.date,unitId:c.unitId,clientId:c.clientId,serviceId:commissionServiceIdFromName(a.service),serviceName:a.service||'Serviço',professionalId:commissionProIdFromName(a.professional),professionalName:a.professional||'',gross:Math.max(0,Number(a.value||0)),manualDiscount:0,lineId:a.id||String(i)}));
}
function commissionApplyComboAllocation(c,rows){
  let map=new Map(rows.map(r=>[r.lineId,r]));
  rows.forEach(r=>{r.netBeforeCombo=Math.max(0,r.gross-r.manualDiscount);r.comboDiscount=0});
  let apps=[];try{if(typeof commandComboApplications==='function')apps=commandComboApplications(c)||[]}catch(e){}
  for(const a of apps){let picked=(a.picks||[]).map(k=>map.get(k)).filter(Boolean);if(!picked.length)continue;let denom=picked.reduce((s,r)=>s+r.netBeforeCombo,0)||picked.length;for(const r of picked){let share=denom?Number(a.discount||0)*(r.netBeforeCombo/denom):Number(a.discount||0)/picked.length;r.comboDiscount+=share}}
  rows.forEach(r=>{r.netCommercial=Math.max(0,r.netBeforeCombo-r.comboDiscount)});return rows
}
function commissionServiceItems(){let out=[];for(const c of (db.clientCommands||[]).filter(c=>c.status==='Pago')){let rows=commissionApplyComboAllocation(c,commissionCommandServiceLines(c));for(const r of rows){let pct=commissionPercent(r.serviceId,r.professionalId),base=db.commissionSettings.discountsReduceBase!==false?r.netCommercial:r.gross,amount=base*pct/100;out.push({...r,type:'service',pct,base,amount,description:r.serviceName,detail:`${pct?String(pct).replace('.',',')+'%':'Sem comissão configurada'} · base ${money(base)}`})}}return out}
function commissionDirectPaymentItems(){let out=[];for(const c of (db.clientCommands||[]).filter(c=>c.status==='Pago')){let prs=[...new Set(commissionCommandServiceLines(c).map(x=>x.professionalId).filter(Boolean))];let recs=Array.isArray(c.paymentRecords)?c.paymentRecords:[];for(let i=0;i<recs.length;i++){let p=recs[i];if(p.methodId!=='pm_direct'||!(Number(p.amount)>0))continue;let pid=p.professionalId||(prs.length===1?prs[0]:'');if(!pid)continue;out.push({type:'direct',key:`direct:${c.id}:${p.id||i}`,date:c.date,unitId:c.unitId,professionalId:pid,amount:-Math.abs(Number(p.amount||0)),description:'Pagamento direto à profissional',detail:`Recebido diretamente na comanda #${String(c.id).replace(/\D/g,'')||c.id}`,commandId:c.id})}}return out}
function commissionTipItems(){return (db.tipMovements||[]).map(t=>({type:'tip',key:`tip:${t.id}`,date:t.date,unitId:t.unitId,professionalId:t.professionalId,amount:Math.max(0,Number(t.net||0)),description:'Gorjeta líquida a repassar',detail:`Bruto ${money(t.gross)} · dedução ${money(t.deduction||0)}`,sourceId:t.id}))}
function commissionAdjustmentItems(){return (db.professionalCommissionAdjustments||[]).map(a=>({type:a.type==='Vale / adiantamento'?'advance':'adjustment',key:`adj:${a.id}`,date:a.date,unitId:a.unitId,professionalId:a.professionalId,amount:Number(a.amount||0),description:a.type||'Ajuste',detail:a.note||'',sourceId:a.id}))}
function commissionAllItems(){return [...commissionServiceItems(),...commissionTipItems(),...commissionAdjustmentItems(),...(db.commissionSettings.directPaymentReducesSettlement!==false?commissionDirectPaymentItems():[])]}
function commissionSettledKeys(){let set=new Set();for(const s of (db.commissionSettlements||[]))for(const k of (s.includedKeys||[]))set.add(k);return set}
function commissionItemSettled(item){return commissionSettledKeys().has(item.key)}
function commissionItemsFiltered({proId='',unitId='all',from=commissionFrom,to=commissionTo,openOnly=false}={}){let settled=commissionSettledKeys();return commissionAllItems().filter(x=>(!proId||x.professionalId===proId)&&(unitId==='all'||x.unitId===unitId)&&(!from||x.date>=from)&&(!to||x.date<=to)&&(!openOnly||!settled.has(x.key)))}
function commissionSettlementForFilter(proId,unitId='all',from=commissionFrom,to=commissionTo){return (db.commissionSettlements||[]).filter(s=>s.professionalId===proId&&(unitId==='all'||s.unitId===unitId)&&s.periodFrom>=from&&s.periodTo<=to)}
function commissionSummaryForPro(proId){let all=commissionItemsFiltered({proId,unitId:commissionUnit,from:commissionFrom,to:commissionTo}),open=all.filter(x=>!commissionItemSettled(x));let service=all.filter(x=>x.type==='service'),tips=all.filter(x=>x.type==='tip'),adv=all.filter(x=>['advance','adjustment'].includes(x.type)),direct=all.filter(x=>x.type==='direct'),settlements=commissionSettlementForFilter(proId,commissionUnit,commissionFrom,commissionTo);return{all,open,serviceBase:service.reduce((s,x)=>s+Number(x.base||0),0),generated:service.reduce((s,x)=>s+Number(x.amount||0),0),tips:tips.reduce((s,x)=>s+Number(x.amount||0),0),adjustments:adv.reduce((s,x)=>s+Number(x.amount||0),0),direct:Math.abs(direct.reduce((s,x)=>s+Number(x.amount||0),0)),settled:settlements.reduce((s,x)=>s+Number(x.total||0),0),due:open.reduce((s,x)=>s+Number(x.amount||0),0)}}
function commissionCurrentPros(){return db.pros.filter(p=>p.active&&(commissionPro==='all'||p.id===commissionPro)&&(commissionUnit==='all'||p.units.includes(commissionUnit)))}
function commissionSetFilter(k,v){if(k==='from')commissionFrom=v;if(k==='to')commissionTo=v;if(k==='unit')commissionUnit=v;if(k==='pro')commissionPro=v;renderCommissionCenter()}
function commissionResetFilters(){let today=(typeof financeToday!=='undefined'?financeToday:localDateISO()),m=today.slice(0,7);commissionFrom=m+'-01';commissionTo=today;commissionUnit='all';commissionPro='all';renderCommissionCenter()}
function renderCommissionCenter(){commissionEnsureDateDefaults();let ps=commissionCurrentPros(),summaries=ps.map(p=>({p,s:commissionSummaryForPro(p.id)}));let totalGenerated=summaries.reduce((q,x)=>q+x.s.generated,0),totalTips=summaries.reduce((q,x)=>q+x.s.tips,0),totalAdv=summaries.reduce((q,x)=>q+x.s.adjustments,0),totalDirect=summaries.reduce((q,x)=>q+x.s.direct,0),totalDue=summaries.reduce((q,x)=>q+x.s.due,0);let rows=summaries.map(({p,s})=>`<tr class="clickable" onclick="openCommissionProfessional('${p.id}')"><td><b>${escapeHtml(p.name)}</b><div class="muted" style="font-size:10px">${escapeHtml(p.specialty||'')}</div></td><td class="num">${money(s.serviceBase)}</td><td class="num"><b>${money(s.generated)}</b></td><td class="num">${money(s.tips)}</td><td class="num ${s.adjustments<0?'negative':''}">${s.adjustments<0?'− ':''}${money(Math.abs(s.adjustments))}</td><td class="num">${money(s.direct)}</td><td class="num">${money(s.settled)}</td><td class="num"><span class="commission-balance ${s.due>=0?'positive':'negative'}">${money(s.due)}</span></td><td class="num"><button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openCommissionProfessional('${p.id}')">Abrir extrato</button></td></tr>`).join('');
 adminPage.innerHTML=`<div class="page-head"><div><h1>Comissões & Acertos</h1><div class="muted">Comissão gerada pelo serviço realizado, gorjetas, vales, pagamentos diretos e ajustes no mesmo extrato.</div></div><div class="spacer"></div><button class="btn btn-soft" onclick="openCommissionSettings()">Regras</button></div><div class="commission-toolbar"><div class="field"><label>De</label><input type="date" value="${commissionFrom}" onchange="commissionSetFilter('from',this.value)"></div><div class="field"><label>Até</label><input type="date" value="${commissionTo}" onchange="commissionSetFilter('to',this.value)"></div><div class="field"><label>Unidade</label><select onchange="commissionSetFilter('unit',this.value)"><option value="all">Todas</option>${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${commissionUnit===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Profissional</label><select onchange="commissionSetFilter('pro',this.value)"><option value="all">Todas</option>${db.pros.filter(p=>p.active).map(p=>`<option value="${p.id}" ${commissionPro===p.id?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="spacer"></div><button class="btn btn-ghost btn-sm" onclick="commissionResetFilters()">Limpar filtros</button></div>
 <div class="commission-kpis"><div class="commission-kpi"><span>Comissão gerada</span><b>${money(totalGenerated)}</b><small>Somente serviços concluídos/pagos no período.</small></div><div class="commission-kpi"><span>Gorjetas líquidas</span><b>${money(totalTips)}</b><small>Separadas da comissão.</small></div><div class="commission-kpi"><span>Vales / ajustes</span><b>${money(totalAdv)}</b><small>Valores negativos reduzem o próximo acerto.</small></div><div class="commission-kpi"><span>Recebido direto</span><b>${money(totalDirect)}</b><small>Abate o que a empresa ainda precisa repassar.</small></div><div class="commission-kpi ${totalDue>=0?'positive':'negative'}"><span>Saldo aberto a pagar</span><b>${money(totalDue)}</b><small>Somente itens ainda não incluídos em acerto fechado.</small></div></div>
 <div class="commission-rule-box"><div class="commission-rule"><b>Combos e descontos</b>O valor comercial é distribuído entre os serviços proporcionalmente e ${db.commissionSettings.discountsReduceBase!==false?'reduz':'não reduz'} a base de comissão.</div><div class="commission-rule"><b>Pacotes</b>A venda do pacote não gera comissão. A comissão nasce quando cada serviço do pacote for efetivamente consumido.</div></div>
 <div class="commission-card"><div class="commission-card-head"><div><h3>Visão geral por profissional</h3><div class="sub">Clique em uma profissional para abrir o extrato completo e fechar o acerto.</div></div></div><div class="commission-table-wrap"><table class="commission-table"><thead><tr><th>Profissional</th><th class="num">Base dos serviços</th><th class="num">Comissão gerada</th><th class="num">Gorjetas</th><th class="num">Vales / ajustes</th><th class="num">Recebido direto</th><th class="num">Já acertado</th><th class="num">Saldo aberto</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="9" class="commission-empty">Nenhuma profissional encontrada neste filtro.</td></tr>'}</tbody></table></div></div>
 <div class="commission-explain"><b>Importante:</b> pagar a comissão não gera uma segunda despesa no DRE. O custo da comissão é reconhecido quando o serviço é realizado; o acerto apenas quita o valor devido à profissional e movimenta a conta financeira escolhida.</div>`}
function commissionTypeLabel(x){return x.type==='service'?'Serviço':x.type==='tip'?'Gorjeta':x.type==='advance'?'Vale':x.type==='direct'?'Pagamento direto':'Ajuste'}
function commissionTypeClass(x){return x.type==='service'?'service':x.type==='tip'?'tip':x.type==='advance'?'advance':x.type==='direct'?'direct':'adjustment'}
function openCommissionProfessional(proId){let p=db.pros.find(x=>x.id===proId);if(!p)return;let s=commissionSummaryForPro(proId),items=s.all.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))),rows=items.map(x=>`<tr><td>${formatDateBR(x.date)}</td><td><span class="commission-kind ${commissionTypeClass(x)}">${commissionTypeLabel(x)}</span></td><td><b>${escapeHtml(x.description||'')}</b><div class="muted" style="font-size:10px;margin-top:3px">${escapeHtml(x.detail||'')}</div></td><td class="num">${x.type==='service'?money(x.base):'—'}</td><td class="num">${x.type==='service'?(x.pct?String(x.pct).replace('.',',')+'%':'—'):'—'}</td><td class="num ${Number(x.amount)<0?'negative':'positive'}">${Number(x.amount)<0?'− ':''}${money(Math.abs(Number(x.amount||0)))}</td><td>${commissionItemSettled(x)?'<span class="commission-chip ok">Acertado</span>':'<span class="commission-chip warn">No saldo</span>'}</td></tr>`).join('');let settlements=commissionSettlementForFilter(proId,commissionUnit,commissionFrom,commissionTo).sort((a,b)=>String(b.paidAt||b.createdAt).localeCompare(String(a.paidAt||a.createdAt)));modal(`Extrato · ${p.name}`,`<div class="commission-detail-grid"><div class="commission-detail-box"><span>Comissão gerada</span><b>${money(s.generated)}</b></div><div class="commission-detail-box"><span>Gorjetas</span><b>${money(s.tips)}</b></div><div class="commission-detail-box"><span>Vales / ajustes</span><b>${money(s.adjustments)}</b></div><div class="commission-detail-box"><span>Recebido direto</span><b>${money(s.direct)}</b></div><div class="commission-detail-box"><span>Saldo aberto</span><b>${money(s.due)}</b></div></div><div class="inline-note"><b>Período:</b> ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)} · <b>Unidade:</b> ${commissionUnit==='all'?'Todas':escapeHtml(financeUnitLabel(commissionUnit))}</div><div class="commission-card" style="margin-top:12px"><div class="commission-table-wrap"><table class="commission-table"><thead><tr><th>Data</th><th>Tipo</th><th>Origem</th><th class="num">Base</th><th class="num">%</th><th class="num">Valor</th><th>Status</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="commission-empty">Sem movimentos no período.</td></tr>'}</tbody></table></div></div>${settlements.length?`<div class="inline-note"><b>Acertos fechados neste filtro:</b><br>${settlements.map(x=>`${formatDateBR(x.paidDate||x.periodTo)} · ${money(x.total)} · ${escapeHtml(x.paymentMethod||'')}`).join('<br>')}</div>`:''}`,`<button class="btn btn-ghost" onclick="closeModal();openCommissionAdjustment('${proId}')">+ Ajuste</button><button class="btn btn-ghost" onclick="copyCommissionSummary('${proId}')">Copiar WhatsApp</button><button class="btn btn-ghost" onclick="closeModal()">Fechar</button><button class="btn btn-primary" ${s.open.length?'':'disabled'} onclick="closeModal();openCommissionSettlement('${proId}')">Fechar acerto</button>`);setTimeout(()=>document.querySelector('#modalHost .modal')?.classList.add('modal-wide'),0)}
function openCommissionAdjustment(proId){let p=db.pros.find(x=>x.id===proId);if(!p)return;modal(`Ajuste de comissão · ${p.name}`,`<div class="form-grid"><div class="field"><label>Data</label><input id="comAdjDate" type="date" value="${commissionTo}"></div><div class="field"><label>Unidade</label><select id="comAdjUnit">${db.units.filter(u=>p.units.includes(u.id)).map(u=>`<option value="${u.id}" ${commissionUnit===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Tipo</label><select id="comAdjType"><option value="Ajuste positivo">Ajuste positivo</option><option value="Ajuste negativo">Ajuste negativo</option><option value="Bônus">Bônus</option><option value="Desconto autorizado">Desconto autorizado</option></select></div><div class="field"><label>Valor</label><input id="comAdjAmount" type="number" min="0" step="0.01" placeholder="0,00"></div><div class="field full"><label>Motivo</label><input id="comAdjNote" placeholder="Descreva o motivo do ajuste"></div></div><div class="inline-note">Ajustes ficam no histórico. Depois de entrarem em um acerto fechado, não são apagados; uma correção posterior deve ser registrada como novo ajuste.</div>`,`<button class="btn btn-ghost" onclick="closeModal();openCommissionProfessional('${proId}')">Voltar</button><button class="btn btn-primary" onclick="saveCommissionAdjustment('${proId}')">Salvar ajuste</button>`)}
function saveCommissionAdjustment(proId){let amount=Math.max(0,Number(document.getElementById('comAdjAmount')?.value||0)),type=document.getElementById('comAdjType')?.value||'Ajuste positivo';if(!(amount>0)){toast('Informe um valor válido');return}let negative=type==='Ajuste negativo'||type==='Desconto autorizado';db.professionalCommissionAdjustments.push({id:'adj'+Date.now(),professionalId:proId,unitId:document.getElementById('comAdjUnit')?.value||'',date:document.getElementById('comAdjDate')?.value||commissionTo,type,amount:negative?-amount:amount,status:'Pendente de acerto',note:document.getElementById('comAdjNote')?.value.trim()||'',createdBy:currentUserName(),createdAt:new Date().toISOString()});save();closeModal();openCommissionProfessional(proId);toast('Ajuste registrado ✓')}
function openCommissionSettings(){let s=db.commissionSettings;modal('Regras de comissão',`<div class="form-grid"><div class="field full"><label class="check"><input id="comSetDiscount" type="checkbox" ${s.discountsReduceBase!==false?'checked':''}> Descontos e combos reduzem a base de comissão</label><div class="help">Recomendado para que a comissão acompanhe o valor comercial efetivamente cobrado do serviço.</div></div><div class="field full"><label class="check"><input id="comSetDirect" type="checkbox" ${s.directPaymentReducesSettlement!==false?'checked':''}> Pagamentos feitos direto à profissional reduzem o próximo acerto</label></div></div><div class="inline-note"><b>Pacotes:</b> comissão somente no consumo do serviço. <b>Gorjetas:</b> ficam separadas da comissão e entram no acerto pelo valor líquido a repassar.</div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveCommissionSettings()">Salvar regras</button>`)}
function saveCommissionSettings(){db.commissionSettings.discountsReduceBase=!!document.getElementById('comSetDiscount')?.checked;db.commissionSettings.directPaymentReducesSettlement=!!document.getElementById('comSetDirect')?.checked;save();closeModal();renderCommissionCenter();toast('Regras de comissão atualizadas ✓')}
function commissionPaymentAccountOptions(proId){let p=db.pros.find(x=>x.id===proId),units=commissionUnit==='all'?(p?.units||[]):[commissionUnit];return (db.financialAccounts||[]).filter(a=>a.active!==false&&units.includes(a.unitId)).map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}
function openCommissionSettlement(proId){let p=db.pros.find(x=>x.id===proId),open=commissionItemsFiltered({proId,unitId:commissionUnit,from:commissionFrom,to:commissionTo,openOnly:true}),total=open.reduce((s,x)=>s+Number(x.amount||0),0);if(!p||!open.length){toast('Não há itens em aberto neste filtro');return}modal(`Fechar acerto · ${p.name}`,`<div class="inline-note"><b>Período:</b> ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}<br>O acerto congela os itens incluídos. Correções posteriores entram como novos ajustes, preservando a auditoria.</div><div class="commission-detail-grid" style="margin-top:12px"><div class="commission-detail-box"><span>Itens em aberto</span><b>${open.length}</b></div><div class="commission-detail-box"><span>Serviços</span><b>${money(open.filter(x=>x.type==='service').reduce((s,x)=>s+x.amount,0))}</b></div><div class="commission-detail-box"><span>Gorjetas</span><b>${money(open.filter(x=>x.type==='tip').reduce((s,x)=>s+x.amount,0))}</b></div><div class="commission-detail-box"><span>Vales / ajustes</span><b>${money(open.filter(x=>['advance','adjustment'].includes(x.type)).reduce((s,x)=>s+x.amount,0))}</b></div><div class="commission-detail-box"><span>Recebido direto</span><b>${money(Math.abs(open.filter(x=>x.type==='direct').reduce((s,x)=>s+x.amount,0)))}</b></div></div><div class="form-grid"><div class="field"><label>Data do pagamento</label><input id="comSettleDate" type="date" value="${commissionTo}"></div><div class="field"><label>Forma</label><select id="comSettleMethod"><option>Pix</option><option>Transferência bancária</option><option>Dinheiro</option><option>Outro</option></select></div><div class="field full"><label>Conta de pagamento</label><select id="comSettleAccount">${commissionPaymentAccountOptions(proId)}</select></div><div class="field full"><label>Observação</label><textarea id="comSettleNote" rows="2" placeholder="Opcional"></textarea></div></div><div class="commission-settlement-total"><span><b>Valor líquido do acerto</b><div class="muted" style="font-size:10px">Comissão + gorjetas + ajustes − vales − pagamentos diretos</div></span><b class="${total>=0?'positive':'negative'}">${money(total)}</b></div>${total<0?'<div class="inline-note" style="margin-top:10px"><b>Saldo negativo:</b> a profissional já recebeu/adiantou mais do que o gerado neste período. Não haverá pagamento; o saldo permanece para compensação futura.</div>':''}`,`<button class="btn btn-ghost" onclick="closeModal();openCommissionProfessional('${proId}')">Voltar</button><button class="btn btn-primary" ${total>0?'':'disabled'} onclick="saveCommissionSettlement('${proId}')">${total>0?'Confirmar acerto':'Sem valor a pagar'}</button>`)}
function saveCommissionSettlement(proId){let open=commissionItemsFiltered({proId,unitId:commissionUnit,from:commissionFrom,to:commissionTo,openOnly:true});if(!open.length){toast('Nenhum item em aberto');return}let total=open.reduce((s,x)=>s+Number(x.amount||0),0);if(total<=0){toast('O saldo está zerado ou negativo e permanece em aberto para compensação futura');return}let paidDate=document.getElementById('comSettleDate')?.value||commissionTo,accountId=document.getElementById('comSettleAccount')?.value||'',account=db.financialAccounts.find(x=>x.id===accountId),p=db.pros.find(x=>x.id===proId),unitId=commissionUnit==='all'?(account?.unitId||p?.units?.[0]||''):commissionUnit,s={id:'cs'+Date.now(),professionalId:proId,unitId,periodFrom:commissionFrom,periodTo:commissionTo,total,includedKeys:open.map(x=>x.key),paidDate,paymentMethod:document.getElementById('comSettleMethod')?.value||'',accountId,accountName:account?.name||'',note:document.getElementById('comSettleNote')?.value.trim()||'',createdAt:new Date().toISOString(),createdBy:currentUserName(),status:'Fechado'};db.commissionSettlements.push(s);for(const x of open){if(x.type==='tip'){let t=db.tipMovements.find(a=>`tip:${a.id}`===x.key);if(t)t.status='Repassada'}if(['advance','adjustment'].includes(x.type)){let a=db.professionalCommissionAdjustments.find(a=>`adj:${a.id}`===x.key);if(a)a.status='Compensado'}}if(total>0)db.demoFinancialEntries.push({id:'fe_comm'+Date.now(),unitId,amount:-total,nature:'Pagamento de comissão',category:'Comissões',professionalId:proId,professionalName:p?.name||'',account:account?.name||'',date:paidDate,origin:`Acerto ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}`,dreImpact:false});save();closeModal();renderCommissionCenter();toast('Acerto fechado e histórico preservado ✓')}
async function copyCommissionSummary(proId){let p=db.pros.find(x=>x.id===proId),s=commissionSummaryForPro(proId);if(!p)return;let text=`Acerto de comissão — ${p.name}\nPeríodo: ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}\n\nComissão gerada: ${money(s.generated)}\nGorjetas líquidas: ${money(s.tips)}\nVales / ajustes: ${money(s.adjustments)}\nRecebido direto: ${money(s.direct)}\nSaldo em aberto: ${money(s.due)}`;await copyTextSafe(text);toast('Resumo copiado para o WhatsApp ✓')}

/* Pagamento direto agora identifica quem recebeu, para o acerto descontar corretamente. */
const _normalizePaymentDraftV44Base=normalizePaymentDraft;
normalizePaymentDraft=function(c){let r=_normalizePaymentDraftV44Base(c);r.forEach(p=>{if(p.professionalId===undefined)p.professionalId=''});return r}
function paymentDirectProOptionsV44(c,selected=''){let ids=[...new Set((c.lines||[]).map(l=>l.professionalId).filter(Boolean))],ps=ids.map(id=>db.pros.find(p=>p.id===id)).filter(Boolean);if(!ps.length)ps=db.pros.filter(p=>p.active);return `<option value="">Selecione</option>${ps.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}`}
paymentLineHtml=function(c,p,i){let noAcc=!paymentNeedsAccount(p.methodId),direct=p.methodId==='pm_direct';return `<div class="payment-line ${direct?'v44-direct':''}" data-pay-index="${i}"><div class="field"><label>Forma de pagamento</label><select class="pay-method" onchange="paymentMethodChanged('${c.id}',${i},this.value)">${paymentMethodOptions(p.methodId)}</select></div><div class="field"><label>Conta / destino</label><select class="pay-account" ${noAcc?'disabled':''} onchange="paymentRefreshTotals('${c.id}')">${paymentAccountOptions(c.unitId,p.methodId,p.accountId,noAcc)}</select></div>${direct?`<div class="field"><label>Profissional que recebeu</label><select class="pay-professional" onchange="paymentRefreshTotals('${c.id}')">${paymentDirectProOptionsV44(c,p.professionalId||'')}</select></div>`:''}<div class="field"><label>Valor</label><input class="pay-amount" type="number" min="0" step="0.01" value="${Number(p.amount||0)}" oninput="paymentRefreshTotals('${c.id}')"></div><button class="btn btn-danger btn-sm" title="Remover" onclick="paymentRemoveLine('${c.id}',${i})">×</button></div>`}
const _paymentReadDraftV44Base=paymentReadDraft;
paymentReadDraft=function(c){_paymentReadDraftV44Base(c);document.querySelectorAll('[data-pay-index]').forEach(row=>{let i=Number(row.dataset.payIndex),p=c.paymentDraft[i];if(!p)return;let pro=row.querySelector('.pay-professional');if(pro)p.professionalId=pro.value||''});return c}
const _finalizeCommandPaymentV44Base=finalizeCommandPayment;
finalizeCommandPayment=function(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(!c)return;try{paymentReadDraft(c)}catch(e){}let snapshot=structuredClone(c.paymentDraft||[]),before=c.status;for(const p of snapshot){if(p.methodId==='pm_direct'&&Number(p.amount)>0&&!p.professionalId){toast('Selecione a profissional que recebeu o pagamento direto');return}}_finalizeCommandPaymentV44Base(cmdId);c=db.clientCommands.find(x=>x.id===cmdId);if(c&&before!=='Pago'&&c.status==='Pago'){c.paymentRecords=snapshot.map(p=>({id:p.id||('pr'+Date.now()+Math.random()),methodId:p.methodId,amount:Number(p.amount||0),accountId:p.accountId||'',processorFee:Number(p.processorFee||0),professionalId:p.professionalId||''}));save()}}

/* ===== V45 · PAGAMENTO DIRETO + ACERTO PARCIAL + RECIBO ===== */
if(!Array.isArray(db.commissionPayments))db.commissionPayments=[];

// Pagamento direto à profissional: o dinheiro não entra no caixa da empresa.
// Ele é tratado como compensação financeira e reduz o saldo do acerto da profissional.
const _normalizePaymentDraftV45Base=normalizePaymentDraft;
normalizePaymentDraft=function(c){let r=_normalizePaymentDraftV45Base(c);r.forEach(p=>{if(p.directChannel===undefined)p.directChannel='Pix direto à profissional'});return r};
function paymentDirectChannelOptionsV45(selected=''){return ['Pix direto à profissional','Dinheiro entregue à profissional','Outro recebimento direto'].map(x=>`<option ${selected===x?'selected':''}>${x}</option>`).join('')}
paymentLineHtml=function(c,p,i){let noAcc=!paymentNeedsAccount(p.methodId),direct=p.methodId==='pm_direct';return `<div class="payment-line ${direct?'v44-direct':''}" data-pay-index="${i}"><div class="field"><label>Forma de pagamento</label><select class="pay-method" onchange="paymentMethodChanged('${c.id}',${i},this.value)">${paymentMethodOptions(p.methodId)}</select></div><div class="field"><label>Conta / destino</label><select class="pay-account" ${noAcc?'disabled':''} onchange="paymentRefreshTotals('${c.id}')">${paymentAccountOptions(c.unitId,p.methodId,p.accountId,noAcc)}</select></div>${direct?`<div class="field"><label>Profissional que recebeu</label><select class="pay-professional" onchange="paymentRefreshTotals('${c.id}')">${paymentDirectProOptionsV44(c,p.professionalId||'')}</select></div><div class="field"><label>Como recebeu</label><select class="pay-direct-channel" onchange="paymentRefreshTotals('${c.id}')">${paymentDirectChannelOptionsV45(p.directChannel||'Pix direto à profissional')}</select></div>`:''}<div class="field"><label>Valor</label><input class="pay-amount" type="number" min="0" step="0.01" value="${Number(p.amount||0)}" oninput="paymentRefreshTotals('${c.id}')"></div><button class="btn btn-danger btn-sm" title="Remover" onclick="paymentRemoveLine('${c.id}',${i})">×</button></div>`};
const _paymentReadDraftV45Base=paymentReadDraft;
paymentReadDraft=function(c){_paymentReadDraftV45Base(c);document.querySelectorAll('[data-pay-index]').forEach(row=>{let i=Number(row.dataset.payIndex),p=c.paymentDraft[i];if(!p)return;let pro=row.querySelector('.pay-professional'),ch=row.querySelector('.pay-direct-channel');if(pro)p.professionalId=pro.value||'';if(ch)p.directChannel=ch.value||'Pix direto à profissional'});return c};
const _finalizeCommandPaymentV45Base=finalizeCommandPayment;
finalizeCommandPayment=function(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(!c)return;try{paymentReadDraft(c)}catch(e){}let snapshot=structuredClone(c.paymentDraft||[]),before=c.status;for(const p of snapshot){if(p.methodId==='pm_direct'&&Number(p.amount)>0&&!p.professionalId){toast('Selecione a profissional que recebeu o pagamento direto');return}}_finalizeCommandPaymentV45Base(cmdId);c=db.clientCommands.find(x=>x.id===cmdId);if(c&&before!=='Pago'&&c.status==='Pago'){
 c.paymentRecords=snapshot.map(p=>({id:p.id||('pr'+Date.now()+Math.random()),methodId:p.methodId,amount:Number(p.amount||0),accountId:p.accountId||'',processorFee:Number(p.processorFee||0),professionalId:p.professionalId||'',directChannel:p.directChannel||''}));
 // Registro financeiro apenas para rastreabilidade/compensação: não altera caixa, tesouraria ou DRE.
 snapshot.filter(p=>p.methodId==='pm_direct'&&Number(p.amount)>0&&p.professionalId).forEach((p,idx)=>{let pro=db.pros.find(x=>x.id===p.professionalId);db.demoFinancialEntries.push({id:'fe_direct_'+Date.now()+'_'+idx,unitId:c.unitId,amount:Number(p.amount||0),referenceAmount:Number(p.amount||0),nature:'Compensação com profissional',category:'Recebimento direto',professionalId:p.professionalId,professionalName:pro?.name||'',account:'Recebido pela profissional',date:c.date,origin:`Comanda #${String(c.id).replace(/\D/g,'')||c.id} · ${p.directChannel||'Recebimento direto'}`,dreImpact:false,cashImpact:false,treasuryImpact:false,nonCash:true});});
 save();
 }};

// Pagamentos de comissão passam a ser movimentos separados, permitindo pagamento parcial.
const _commissionAllItemsV45Base=commissionAllItems;
commissionAllItems=function(){let base=_commissionAllItemsV45Base();let pays=(db.commissionPayments||[]).map(p=>({type:'settlement_payment',key:`cpay:${p.id}`,date:p.paidDate,unitId:p.unitId,professionalId:p.professionalId,amount:-Math.abs(Number(p.amount||0)),description:'Pagamento de acerto',detail:`${p.paymentMethod||'Pagamento'} · ${p.accountName||'Conta não informada'} · período ${formatDateBR(p.periodFrom)} a ${formatDateBR(p.periodTo)}`,sourceId:p.id}));return [...base,...pays]};
commissionTypeLabel=function(x){return x.type==='service'?'Serviço':x.type==='tip'?'Gorjeta':x.type==='advance'?'Vale':x.type==='direct'?'Recebido direto':x.type==='settlement_payment'?'Pagamento do acerto':'Ajuste'};
commissionTypeClass=function(x){return x.type==='service'?'service':x.type==='tip'?'tip':x.type==='advance'?'advance':x.type==='direct'?'direct':x.type==='settlement_payment'?'direct':'adjustment'};
function commissionPaymentsForFilter(proId,unitId='all',from=commissionFrom,to=commissionTo){return (db.commissionPayments||[]).filter(p=>p.professionalId===proId&&(unitId==='all'||p.unitId===unitId)&&p.periodFrom>=from&&p.periodTo<=to)}
commissionDirectPaymentItems=function(){let out=[];for(const c of (db.clientCommands||[]).filter(c=>c.status==='Pago')){let prs=[...new Set(commissionCommandServiceLines(c).map(x=>x.professionalId).filter(Boolean))],recs=Array.isArray(c.paymentRecords)?c.paymentRecords:[];for(let i=0;i<recs.length;i++){let p=recs[i];if(p.methodId!=='pm_direct'||!(Number(p.amount)>0))continue;let pid=p.professionalId||(prs.length===1?prs[0]:'');if(!pid)continue;out.push({type:'direct',key:`direct:${c.id}:${p.id||i}`,date:c.date,unitId:c.unitId,professionalId:pid,amount:-Math.abs(Number(p.amount||0)),description:'Pagamento direto à profissional',detail:`${p.directChannel||'Recebimento direto'} · comanda #${String(c.id).replace(/\D/g,'')||c.id}`,commandId:c.id})}}return out};
commissionSummaryForPro=function(proId){let all=commissionItemsFiltered({proId,unitId:commissionUnit,from:commissionFrom,to:commissionTo}),open=all.filter(x=>!commissionItemSettled(x));let service=all.filter(x=>x.type==='service'),tips=all.filter(x=>x.type==='tip'),adv=all.filter(x=>['advance','adjustment'].includes(x.type)),direct=all.filter(x=>x.type==='direct'),pays=all.filter(x=>x.type==='settlement_payment'),settlements=commissionSettlementForFilter(proId,commissionUnit,commissionFrom,commissionTo),legacyPaid=settlements.reduce((s,x)=>s+Number(x.total||0),0),newPaid=Math.abs(pays.reduce((s,x)=>s+Number(x.amount||0),0));return{all,open,serviceBase:service.reduce((s,x)=>s+Number(x.base||0),0),generated:service.reduce((s,x)=>s+Number(x.amount||0),0),tips:tips.reduce((s,x)=>s+Number(x.amount||0),0),adjustments:adv.reduce((s,x)=>s+Number(x.amount||0),0),direct:Math.abs(direct.reduce((s,x)=>s+Number(x.amount||0),0)),settled:legacyPaid+newPaid,paid:newPaid,due:open.reduce((s,x)=>s+Number(x.amount||0),0)} };

renderCommissionCenter=function(){commissionEnsureDateDefaults();let ps=commissionCurrentPros(),summaries=ps.map(p=>({p,s:commissionSummaryForPro(p.id)}));let totalGenerated=summaries.reduce((q,x)=>q+x.s.generated,0),totalTips=summaries.reduce((q,x)=>q+x.s.tips,0),totalAdv=summaries.reduce((q,x)=>q+x.s.adjustments,0),totalDirect=summaries.reduce((q,x)=>q+x.s.direct,0),totalPaid=summaries.reduce((q,x)=>q+x.s.settled,0),totalDue=summaries.reduce((q,x)=>q+x.s.due,0);let rows=summaries.map(({p,s})=>`<tr class="clickable" onclick="openCommissionProfessional('${p.id}')"><td><b>${escapeHtml(p.name)}</b><div class="muted" style="font-size:10px">${escapeHtml(p.specialty||'')}</div></td><td class="num">${money(s.serviceBase)}</td><td class="num"><b>${money(s.generated)}</b></td><td class="num">${money(s.tips)}</td><td class="num ${s.adjustments<0?'negative':''}">${s.adjustments<0?'− ':''}${money(Math.abs(s.adjustments))}</td><td class="num">${money(s.direct)}</td><td class="num"><b>${money(s.settled)}</b></td><td class="num"><span class="commission-balance ${s.due>=0?'positive':'negative'}">${money(s.due)}</span></td><td class="num"><button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openCommissionProfessional('${p.id}')">Abrir extrato</button></td></tr>`).join('');adminPage.innerHTML=`<div class="page-head"><div><h1>Comissões & Acertos</h1><div class="muted">Comissão gerada, gorjetas, vales, recebimentos diretos e pagamentos parciais no mesmo extrato.</div></div><div class="spacer"></div><button class="btn btn-soft" onclick="openCommissionSettings()">Regras</button></div><div class="commission-toolbar"><div class="field"><label>De</label><input type="date" value="${commissionFrom}" onchange="commissionSetFilter('from',this.value)"></div><div class="field"><label>Até</label><input type="date" value="${commissionTo}" onchange="commissionSetFilter('to',this.value)"></div><div class="field"><label>Unidade</label><select onchange="commissionSetFilter('unit',this.value)"><option value="all">Todas</option>${db.units.filter(u=>u.active!==false).map(u=>`<option value="${u.id}" ${commissionUnit===u.id?'selected':''}>${escapeHtml(u.name)}</option>`).join('')}</select></div><div class="field"><label>Profissional</label><select onchange="commissionSetFilter('pro',this.value)"><option value="all">Todas</option>${db.pros.filter(p=>p.active).map(p=>`<option value="${p.id}" ${commissionPro===p.id?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="spacer"></div><button class="btn btn-ghost btn-sm" onclick="commissionResetFilters()">Limpar filtros</button></div><div class="commission-kpis"><div class="commission-kpi"><span>Comissão gerada</span><b>${money(totalGenerated)}</b><small>Serviços concluídos/pagos.</small></div><div class="commission-kpi"><span>Gorjetas líquidas</span><b>${money(totalTips)}</b><small>Separadas da comissão.</small></div><div class="commission-kpi"><span>Recebido direto</span><b>${money(totalDirect)}</b><small>Cliente pagou direto à profissional.</small></div><div class="commission-kpi"><span>Pagamentos de acerto</span><b>${money(totalPaid)}</b><small>Inclui pagamentos parciais.</small></div><div class="commission-kpi ${totalDue>=0?'positive':'negative'}"><span>Saldo aberto</span><b>${money(totalDue)}</b><small>Atualiza após cada pagamento.</small></div></div><div class="commission-rule-box"><div class="commission-rule"><b>Pix direto à profissional</b>É registrado na finalização da Comanda. Não entra no Caixa da empresa; vira compensação e reduz o saldo da profissional.</div><div class="commission-rule"><b>Pagamento parcial</b>Você pode pagar qualquer valor até o saldo aberto. O restante continua visível para o próximo acerto.</div></div><div class="commission-card"><div class="commission-card-head"><div><h3>Visão geral por profissional</h3><div class="sub">A coluna “Saldo aberto” mostra exatamente o que ainda falta pagar.</div></div></div><div class="commission-table-wrap"><table class="commission-table"><thead><tr><th>Profissional</th><th class="num">Base dos serviços</th><th class="num">Comissão gerada</th><th class="num">Gorjetas</th><th class="num">Vales / ajustes</th><th class="num">Recebido direto</th><th class="num">Pago no acerto</th><th class="num">Saldo aberto</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="9" class="commission-empty">Nenhuma profissional encontrada.</td></tr>'}</tbody></table></div></div><div class="commission-explain"><b>Financeiro:</b> pagamento direto pela cliente é uma compensação não-caixa. Pagamento do acerto movimenta a conta escolhida, mas não cria nova despesa no DRE porque a comissão já foi reconhecida no serviço.</div>`};

openCommissionProfessional=function(proId){let p=db.pros.find(x=>x.id===proId);if(!p)return;let s=commissionSummaryForPro(proId),items=s.all.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))),rows=items.map(x=>{let status=x.type==='settlement_payment'?'<span class="commission-chip ok">Pago</span>':commissionItemSettled(x)?'<span class="commission-chip ok">Acertado</span>':'<span class="commission-chip warn">Em aberto</span>';return `<tr><td>${formatDateBR(x.date)}</td><td><span class="commission-kind ${commissionTypeClass(x)}">${commissionTypeLabel(x)}</span></td><td><b>${escapeHtml(x.description||'')}</b><div class="muted" style="font-size:10px;margin-top:3px">${escapeHtml(x.detail||'')}</div></td><td class="num">${x.type==='service'?money(x.base):'—'}</td><td class="num">${x.type==='service'?(x.pct?String(x.pct).replace('.',',')+'%':'—'):'—'}</td><td class="num ${Number(x.amount)<0?'negative':'positive'}">${Number(x.amount)<0?'− ':''}${money(Math.abs(Number(x.amount||0)))}</td><td>${status}</td></tr>`}).join('');let pays=commissionPaymentsForFilter(proId,commissionUnit,commissionFrom,commissionTo).sort((a,b)=>String(b.paidDate).localeCompare(String(a.paidDate)));modal(`Extrato · ${p.name}`,`<div class="commission-detail-grid"><div class="commission-detail-box"><span>Comissão gerada</span><b>${money(s.generated)}</b></div><div class="commission-detail-box"><span>Gorjetas</span><b>${money(s.tips)}</b></div><div class="commission-detail-box"><span>Recebido direto</span><b>${money(s.direct)}</b></div><div class="commission-detail-box"><span>Pago em acertos</span><b>${money(s.settled)}</b></div><div class="commission-detail-box"><span>Saldo aberto</span><b>${money(s.due)}</b></div></div><div class="inline-note"><b>Período:</b> ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)} · <b>Unidade:</b> ${commissionUnit==='all'?'Todas':escapeHtml(financeUnitLabel(commissionUnit))}</div><div class="commission-card" style="margin-top:12px"><div class="commission-table-wrap"><table class="commission-table"><thead><tr><th>Data</th><th>Tipo</th><th>Origem</th><th class="num">Base</th><th class="num">%</th><th class="num">Valor</th><th>Status</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="commission-empty">Sem movimentos no período.</td></tr>'}</tbody></table></div></div>${pays.length?`<div class="inline-note"><b>Pagamentos realizados:</b><br>${pays.map(x=>`${formatDateBR(x.paidDate)} · ${money(x.amount)} · ${escapeHtml(x.paymentMethod||'')} · <button class="btn btn-ghost btn-sm" onclick="openCommissionReceipt('${x.id}')">Recibo</button>`).join('<br>')}</div>`:''}`,`<button class="btn btn-ghost" onclick="closeModal();openCommissionAdjustment('${proId}')">+ Ajuste</button><button class="btn btn-ghost" onclick="copyCommissionSummary('${proId}')">Copiar WhatsApp</button><button class="btn btn-ghost" onclick="closeModal()">Fechar</button><button class="btn btn-primary" ${s.due>0?'':'disabled'} onclick="closeModal();openCommissionSettlement('${proId}')">Registrar pagamento</button>`);setTimeout(()=>document.querySelector('#modalHost .modal')?.classList.add('modal-wide'),0)};

function commissionSettlementPreviewV45(proId){let s=commissionSummaryForPro(proId),el=document.getElementById('comSettleAmount'),pay=Math.max(0,Number(el?.value||0)),remaining=Math.max(0,s.due-pay),a=document.getElementById('comSettleRemaining');if(a)a.textContent=money(remaining)}
openCommissionSettlement=function(proId){let p=db.pros.find(x=>x.id===proId),s=commissionSummaryForPro(proId),total=s.due;if(!p||!(total>0)){toast('Não há saldo positivo a pagar neste filtro');return}modal(`Registrar pagamento · ${p.name}`,`<div class="inline-note"><b>Período de referência:</b> ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}<br>Você pode pagar o valor total ou apenas uma parte. O saldo restante continuará aparecendo na tela principal de Comissões.</div><div class="commission-detail-grid" style="margin-top:12px"><div class="commission-detail-box"><span>Saldo aberto antes do pagamento</span><b>${money(total)}</b></div><div class="commission-detail-box"><span>Recebido direto de clientes</span><b>${money(s.direct)}</b></div><div class="commission-detail-box"><span>Já pago em acertos</span><b>${money(s.settled)}</b></div></div><div class="form-grid"><div class="field"><label>Data do pagamento</label><input id="comSettleDate" type="date" value="${commissionTo}"></div><div class="field"><label>Forma</label><select id="comSettleMethod"><option>Pix</option><option>Transferência bancária</option><option>Dinheiro</option><option>Outro</option></select></div><div class="field full"><label>Conta de pagamento</label><select id="comSettleAccount">${commissionPaymentAccountOptions(proId)}</select></div><div class="field full"><label><b>Valor que estou pagando agora</b></label><input id="comSettleAmount" type="number" min="0.01" max="${total}" step="0.01" value="${total.toFixed(2)}" oninput="commissionSettlementPreviewV45('${proId}')"><div class="help">Editável. Pode ser menor que o saldo total.</div></div><div class="field full"><label>Observação</label><textarea id="comSettleNote" rows="2" placeholder="Opcional"></textarea></div></div><div class="commission-settlement-total"><span><b>Saldo que ficará após este pagamento</b><div class="muted" style="font-size:10px">O restante continua em aberto para o próximo pagamento.</div></span><b id="comSettleRemaining" class="positive">${money(0)}</b></div>`,`<button class="btn btn-ghost" onclick="closeModal();openCommissionProfessional('${proId}')">Voltar</button><button class="btn btn-primary" onclick="saveCommissionSettlement('${proId}')">Confirmar pagamento e gerar recibo</button>`)};

saveCommissionSettlement=function(proId){let p=db.pros.find(x=>x.id===proId),s=commissionSummaryForPro(proId),due=s.due,amount=roundMoney(Math.max(0,Number(document.getElementById('comSettleAmount')?.value||0)));if(!p||!(due>0)){toast('Não há saldo a pagar');return}if(!(amount>0)){toast('Informe o valor que está pagando');return}if(amount>due+.009){toast('O valor do pagamento não pode ultrapassar o saldo aberto');return}let paidDate=document.getElementById('comSettleDate')?.value||commissionTo,accountId=document.getElementById('comSettleAccount')?.value||'',account=db.financialAccounts.find(x=>x.id===accountId),unitId=commissionUnit==='all'?(account?.unitId||p?.units?.[0]||''):commissionUnit,pay={id:'cp'+Date.now(),professionalId:proId,professionalName:p.name,unitId,periodFrom:commissionFrom,periodTo:commissionTo,amount,paidDate,paymentMethod:document.getElementById('comSettleMethod')?.value||'Pix',accountId,accountName:account?.name||'',note:document.getElementById('comSettleNote')?.value.trim()||'',createdAt:new Date().toISOString(),createdBy:currentUserName()};db.commissionPayments.push(pay);db.demoFinancialEntries.push({id:'fe_comm_pay'+Date.now(),unitId,amount:-amount,nature:'Pagamento de comissão',category:'Comissões',professionalId:proId,professionalName:p.name,account:account?.name||'',date:paidDate,origin:`Pagamento de acerto ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}`,dreImpact:false});save();closeModal();renderCommissionCenter();openCommissionReceipt(pay.id);toast(amount+0.009<due?'Pagamento parcial registrado · saldo restante mantido ✓':'Pagamento do acerto registrado ✓')};

function commissionReceiptTextV45(pay){let p=db.pros.find(x=>x.id===pay.professionalId),u=db.units.find(x=>x.id===pay.unitId);return `RECIBO DE PAGAMENTO DE COMISSÃO\n\nData do pagamento: ${formatDateBR(pay.paidDate)}\nProfissional: ${p?.name||pay.professionalName||''}\nUnidade: ${u?.name||''}\nPeríodo trabalhado: ${formatDateBR(pay.periodFrom)} a ${formatDateBR(pay.periodTo)}\nValor recebido: ${money(pay.amount)}\nForma de pagamento: ${pay.paymentMethod||''}\nConta de saída: ${pay.accountName||''}${pay.note?'\nObservação: '+pay.note:''}\n\nDeclaro o recebimento do valor acima referente ao período informado.\n\n__________________________________\nAssinatura da profissional`}
async function copyCommissionReceiptV45(id){let pay=(db.commissionPayments||[]).find(x=>x.id===id);if(!pay)return;await copyTextSafe(commissionReceiptTextV45(pay));toast('Recibo copiado ✓')}
function printCommissionReceiptV45(id){let pay=(db.commissionPayments||[]).find(x=>x.id===id);if(!pay)return;let txt=commissionReceiptTextV45(pay),w=window.open('','_blank','width=760,height=700');if(!w){toast('O navegador bloqueou a janela de impressão');return}w.document.write(`<html><head><title>Recibo de comissão</title><style>body{font-family:Arial,sans-serif;color:#222;padding:42px;line-height:1.55}.box{border:1px solid #bbb;border-radius:12px;padding:26px;max-width:680px;margin:auto}h1{font-size:20px;margin:0 0 24px}pre{font:14px/1.6 Arial,sans-serif;white-space:pre-wrap}.muted{color:#666;font-size:12px;margin-top:24px}@media print{button{display:none}.box{border:0}}</style>
<style>
.v46-rem-label{font-weight:700}.v46-partnership-card b{color:#5d2f69}
</style>
</head><body><div class="box"><pre>${escapeHtml(txt)}</pre><div class="muted">Gerado pelo Império das Unhas · ${escapeHtml(currentUserName())}</div><button onclick="window.print()" style="margin-top:20px;padding:10px 16px">Imprimir / Salvar PDF</button></div>


</body></html>`);w.document.close()}
function openCommissionReceipt(id){let pay=(db.commissionPayments||[]).find(x=>x.id===id);if(!pay)return;let p=db.pros.find(x=>x.id===pay.professionalId),u=db.units.find(x=>x.id===pay.unitId);modal('Recibo de pagamento',`<div style="border:1px solid var(--line);border-radius:14px;padding:20px;background:#fff"><div class="eyebrow">RECIBO DE PAGAMENTO DE COMISSÃO</div><h2 style="margin:6px 0 18px">${escapeHtml(p?.name||pay.professionalName||'Profissional')}</h2><div class="booking-summary"><div class="row"><span>Data do pagamento</span><b>${formatDateBR(pay.paidDate)}</b></div><div class="row"><span>Período trabalhado</span><b>${formatDateBR(pay.periodFrom)} a ${formatDateBR(pay.periodTo)}</b></div><div class="row"><span>Unidade</span><b>${escapeHtml(u?.name||'')}</b></div><div class="row"><span>Valor recebido</span><b>${money(pay.amount)}</b></div><div class="row"><span>Forma</span><b>${escapeHtml(pay.paymentMethod||'')}</b></div><div class="row"><span>Conta de saída</span><b>${escapeHtml(pay.accountName||'')}</b></div></div>${pay.note?`<div class="inline-note" style="margin-top:12px"><b>Observação:</b> ${escapeHtml(pay.note)}</div>`:''}<div style="margin-top:28px;border-top:1px solid #bbb;padding-top:18px;text-align:center;color:var(--muted)">Assinatura da profissional</div></div>`,`<button class="btn btn-ghost" onclick="copyCommissionReceiptV45('${id}')">Copiar</button><button class="btn btn-soft" onclick="printCommissionReceiptV45('${id}')">Imprimir / Salvar PDF</button><button class="btn btn-primary" onclick="closeModal()">Concluir</button>`)}

copyCommissionSummary=function(proId){let p=db.pros.find(x=>x.id===proId),s=commissionSummaryForPro(proId);if(!p)return;let text=`Acerto de comissão — ${p.name}\nPeríodo: ${formatDateBR(commissionFrom)} a ${formatDateBR(commissionTo)}\n\nComissão gerada: ${money(s.generated)}\nGorjetas líquidas: ${money(s.tips)}\nVales / ajustes: ${money(s.adjustments)}\nRecebido direto de clientes: ${money(s.direct)}\nPago em acertos: ${money(s.settled)}\nSaldo ainda em aberto: ${money(s.due)}`;copyTextSafe(text).then(()=>toast('Resumo copiado para o WhatsApp ✓'))};

// ===== V46 · MODELOS DE REMUNERAÇÃO + MODELO/PARCERIA + CONTA MENSAL DE CLIENTE =====
if(!Array.isArray(db.remunerationRules))db.remunerationRules=[];
if(!Array.isArray(db.professionalDailyWork))db.professionalDailyWork=[];
if(!Array.isArray(db.clientReceivables))db.clientReceivables=[];
if(!Array.isArray(db.clientReceivablePayments))db.clientReceivablePayments=[];
if(!db.paymentMethods.some(x=>x.id==='pm_monthly'))db.paymentMethods.push({id:'pm_monthly',name:'Conta mensal / faturar cliente',kind:'receivable',active:true});
(db.clients||[]).forEach(c=>{if(c.monthlyBillingEnabled===undefined)c.monthlyBillingEnabled=false;if(c.monthlyCreditLimit===undefined)c.monthlyCreditLimit=0;if(c.monthlyBillingDay===undefined)c.monthlyBillingDay=30});
save();

function remModelLabel(m){return ({commission:'Somente comissão',fixed:'Valor fixo',guarantee:'Garantia mínima ou comissão',fixed_plus:'Fixo + comissão',daily:'Diária / freelancer',daily_plus:'Diária + comissão'})[m]||'Somente comissão'}
function remFrequencyLabel(f){return ({monthly:'Mensal',fortnightly:'Quinzenal',weekly:'Semanal',settlement:'Por período do acerto',daily:'Por dia trabalhado'})[f]||'Por período do acerto'}
function remunerationRuleFor(proId,unitId,date=''){return (db.remunerationRules||[]).filter(r=>r.active!==false&&r.professionalId===proId&&(!r.unitId||r.unitId===unitId)&&(!date||(!r.startDate||r.startDate<=date)&&(!r.endDate||r.endDate>=date))).sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')))[0]||null}
function remunerationPeriodFactor(rule,from,to){if(!rule)return 0;if(rule.frequency==='settlement')return 1;if(rule.frequency==='weekly'){let d=Math.max(1,Math.round((new Date(to+'T12:00:00')-new Date(from+'T12:00:00'))/86400000)+1);return d/7}if(rule.frequency==='fortnightly'){let d=Math.max(1,Math.round((new Date(to+'T12:00:00')-new Date(from+'T12:00:00'))/86400000)+1);return d/15}if(rule.frequency==='monthly'){let a=new Date(from+'T12:00:00'),b=new Date(to+'T12:00:00');return Math.max(1,(b.getFullYear()-a.getFullYear())*12+(b.getMonth()-a.getMonth())+1)}return 1}
function remunerationFixedValue(rule,from,to){return Math.max(0,Number(rule?.amount||0))*remunerationPeriodFactor(rule,from,to)}
function openRemunerationRules(proId=''){let ps=db.pros.filter(p=>p.active),selected=proId||ps[0]?.id||'',rules=(db.remunerationRules||[]).filter(r=>!selected||r.professionalId===selected).sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')));modal('Modelos de remuneração',`<div class="inline-note"><b>Regra por profissional + unidade + vigência.</b> Assim a mesma profissional pode receber comissão no Centro e diária no Big, sem alterar o histórico antigo.</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Profissional</label><select id="remFilterPro" onchange="closeModal();openRemunerationRules(this.value)">${ps.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></div><div class="field" style="display:flex;align-items:end"><button class="btn btn-primary" onclick="closeModal();openRemunerationRuleForm('${selected}')">+ Nova regra</button></div></div><div class="table-card" style="margin-top:12px"><table class="table"><thead><tr><th>Unidade</th><th>Modelo</th><th>Valor</th><th>Periodicidade</th><th>Vigência</th><th>Status</th><th></th></tr></thead><tbody>${rules.map(r=>`<tr><td>${escapeHtml(financeUnitLabel(r.unitId)||'Todas')}</td><td><b>${escapeHtml(remModelLabel(r.model))}</b></td><td>${['commission'].includes(r.model)?'—':money(r.amount||0)}</td><td>${escapeHtml(remFrequencyLabel(r.frequency))}</td><td>${r.startDate?formatDateBR(r.startDate):'—'} ${r.endDate?'até '+formatDateBR(r.endDate):'em diante'}</td><td>${r.active===false?'Inativa':(r.endDate&&r.endDate<localDateISO()?'Encerrada':'Ativa')}</td><td><button class="btn btn-ghost btn-sm" onclick="closeModal();openRemunerationRuleForm('${selected}','${r.id}')">Editar</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">Nenhuma regra cadastrada. Sem regra, permanece somente comissão.</td></tr>'}</tbody></table></div>`,`<button class="btn btn-ghost" onclick="closeModal()">Fechar</button><button class="btn btn-soft" onclick="closeModal();openDailyWorkForm('${selected}')">Registrar diária trabalhada</button>`);setTimeout(()=>document.querySelector('#modalHost .modal')?.classList.add('modal-wide'),0)}
function openRemunerationRuleForm(proId,id=''){let p=db.pros.find(x=>x.id===proId);if(!p)return;let r=id?db.remunerationRules.find(x=>x.id===id):null;if(!r)r={id:'rr'+Date.now(),professionalId:proId,unitId:p.units?.[0]||'',model:'commission',amount:0,frequency:'settlement',startDate:commissionFrom||localDateISO(),endDate:'',active:true,note:''};modal(`${id?'Editar':'Nova'} regra · ${p.name}`,`<div class="form-grid"><div class="field"><label>Unidade</label><select id="rrUnit">${(p.units||[]).map(uid=>`<option value="${uid}" ${r.unitId===uid?'selected':''}>${escapeHtml(financeUnitLabel(uid))}</option>`).join('')}</select></div><div class="field"><label>Modelo</label><select id="rrModel" onchange="remRuleModelChanged()"><option value="commission" ${r.model==='commission'?'selected':''}>Somente comissão</option><option value="fixed" ${r.model==='fixed'?'selected':''}>Valor fixo</option><option value="guarantee" ${r.model==='guarantee'?'selected':''}>Garantia mínima ou comissão</option><option value="fixed_plus" ${r.model==='fixed_plus'?'selected':''}>Fixo + comissão</option><option value="daily" ${r.model==='daily'?'selected':''}>Diária / freelancer</option><option value="daily_plus" ${r.model==='daily_plus'?'selected':''}>Diária + comissão</option></select></div><div class="field"><label>Valor da regra</label><input id="rrAmount" type="number" min="0" step="0.01" value="${Number(r.amount||0)}"><div class="help">No modelo diária, este é o valor por dia. Na garantia, é o mínimo do período.</div></div><div class="field"><label>Periodicidade</label><select id="rrFrequency"><option value="settlement" ${r.frequency==='settlement'?'selected':''}>Por período do acerto</option><option value="monthly" ${r.frequency==='monthly'?'selected':''}>Mensal</option><option value="fortnightly" ${r.frequency==='fortnightly'?'selected':''}>Quinzenal</option><option value="weekly" ${r.frequency==='weekly'?'selected':''}>Semanal</option><option value="daily" ${r.frequency==='daily'?'selected':''}>Por dia trabalhado</option></select></div><div class="field"><label>Início da vigência</label><input id="rrStart" type="date" value="${r.startDate||''}"></div><div class="field"><label>Fim da vigência</label><input id="rrEnd" type="date" value="${r.endDate||''}"></div><div class="field full"><label>Observação</label><input id="rrNote" value="${escapeAttr(r.note||'')}" placeholder="Ex.: garantia de adaptação pelos primeiros 3 meses"></div><div class="field full"><label class="check"><input id="rrActive" type="checkbox" ${r.active!==false?'checked':''}> Regra ativa</label></div></div><div class="inline-note"><b>Garantia mínima ou comissão:</b> paga o maior entre o mínimo e a comissão gerada. <b>Diária:</b> os serviços continuam registrados para produtividade/faturamento, mas não geram comissão se o modelo for somente diária.</div>`,`<button class="btn btn-ghost" onclick="closeModal();openRemunerationRules('${proId}')">Voltar</button><button class="btn btn-primary" onclick="saveRemunerationRule('${proId}','${id||''}')">Salvar regra</button>`)}
function remRuleModelChanged(){let m=document.getElementById('rrModel')?.value,f=document.getElementById('rrFrequency');if(!f)return;if(['daily','daily_plus'].includes(m))f.value='daily'}
function saveRemunerationRule(proId,id=''){let model=document.getElementById('rrModel')?.value||'commission',amount=Math.max(0,Number(document.getElementById('rrAmount')?.value||0)),unitId=document.getElementById('rrUnit')?.value||'',startDate=document.getElementById('rrStart')?.value||'',endDate=document.getElementById('rrEnd')?.value||'';if(model!=='commission'&&!(amount>0)){toast('Informe o valor da regra');return}let r=id?db.remunerationRules.find(x=>x.id===id):null;if(!r){r={id:'rr'+Date.now(),professionalId:proId};db.remunerationRules.push(r)}Object.assign(r,{unitId,model,amount,frequency:document.getElementById('rrFrequency')?.value||'settlement',startDate,endDate,active:!!document.getElementById('rrActive')?.checked,note:document.getElementById('rrNote')?.value.trim()||''});save();closeModal();openRemunerationRules(proId);toast('Modelo de remuneração salvo ✓')}
function openDailyWorkForm(proId=''){let p=db.pros.find(x=>x.id===proId)||db.pros.find(x=>x.active);if(!p)return;modal(`Registrar diária trabalhada · ${p.name}`,`<div class="form-grid"><div class="field"><label>Data trabalhada</label><input id="dwDate" type="date" value="${commissionTo||localDateISO()}"></div><div class="field"><label>Unidade</label><select id="dwUnit" onchange="dailyWorkSuggestRate('${p.id}')">${(p.units||[]).map(uid=>`<option value="${uid}">${escapeHtml(financeUnitLabel(uid))}</option>`).join('')}</select></div><div class="field"><label>Valor da diária</label><input id="dwAmount" type="number" min="0" step="0.01" value="0"></div><div class="field full"><label>Observação</label><input id="dwNote" placeholder="Ex.: freelancer para cobrir sábado"></div></div><div class="inline-note">A diária é um evento explícito. Ter escala ou poucos atendimentos no dia não cria pagamento sozinho; o gestor confirma que o dia foi efetivamente trabalhado.</div>`,`<button class="btn btn-ghost" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" onclick="saveDailyWork('${p.id}')">Registrar diária</button>`);setTimeout(()=>dailyWorkSuggestRate(p.id),0)}
function dailyWorkSuggestRate(proId){let unit=document.getElementById('dwUnit')?.value,date=document.getElementById('dwDate')?.value||localDateISO(),rule=remunerationRuleFor(proId,unit,date),el=document.getElementById('dwAmount');if(el&&rule&&['daily','daily_plus'].includes(rule.model))el.value=Number(rule.amount||0).toFixed(2)}
function saveDailyWork(proId){let date=document.getElementById('dwDate')?.value,unitId=document.getElementById('dwUnit')?.value,amount=roundMoney(Math.max(0,Number(document.getElementById('dwAmount')?.value||0)));if(!date||!unitId||!(amount>0)){toast('Informe data, unidade e valor da diária');return}if(db.professionalDailyWork.some(x=>x.professionalId===proId&&x.unitId===unitId&&x.date===date)){toast('Essa diária já foi registrada');return}db.professionalDailyWork.push({id:'dw'+Date.now(),professionalId:proId,unitId,date,amount,note:document.getElementById('dwNote')?.value.trim()||'',createdBy:currentUserName(),createdAt:new Date().toISOString()});save();closeModal();renderCommissionCenter();toast('Diária registrada ✓')}

const _commissionServiceItemsV46Base=commissionServiceItems;
commissionServiceItems=function(){let items=_commissionServiceItemsV46Base();for(const x of items){let c=(db.clientCommands||[]).find(z=>z.id===x.commandId);if(c?.partnership?.enabled){let rows=commissionCommandServiceLines(c),denom=rows.reduce((s,r)=>s+Math.max(0,Number(r.gross||0)),0)||1,share=Math.max(0,Number(x.gross||0))/denom,mode=c.partnership.commissionBaseMode||'full',totalBase=mode==='charged'?Math.max(0,Number(c.partnership.chargedValue||0)):mode==='custom'?Math.max(0,Number(c.partnership.customCommissionBase||0)):rows.reduce((s,r)=>s+Math.max(0,Number(r.gross||0)),0);x.base=totalBase*share;x.amount=x.base*x.pct/100;x.detail=`Modelo/Parceria · base de comissão ${money(x.base)} · ${x.pct?String(x.pct).replace('.',',')+'%':'sem % configurado'}`}
 let rule=remunerationRuleFor(x.professionalId,x.unitId,x.date);if(rule&&['fixed','daily'].includes(rule.model)){x.amount=0;x.detail=`${remModelLabel(rule.model)} · produção registrada sem comissão de serviço`}}
 return items}
function remunerationSupplementItems(){let out=[];for(const p of db.pros){let units=commissionUnit==='all'?(p.units||[]):[commissionUnit];for(const uid of units){let rules=(db.remunerationRules||[]).filter(r=>r.active!==false&&r.professionalId===p.id&&r.unitId===uid&&(!r.endDate||r.endDate>=commissionFrom)&&(!r.startDate||r.startDate<=commissionTo)).sort((a,b)=>String(b.startDate||'').localeCompare(String(a.startDate||'')));let r=rules[0];if(!r)continue;if(['fixed','fixed_plus'].includes(r.model)){let v=remunerationFixedValue(r,commissionFrom,commissionTo);if(v>0)out.push({type:'remuneration',key:`rem:${r.id}:${commissionFrom}:${commissionTo}`,date:commissionTo,unitId:uid,professionalId:p.id,amount:v,description:r.model==='fixed'?'Valor fixo':'Parcela fixa',detail:`${remFrequencyLabel(r.frequency)} · regra vigente`})}if(r.model==='guarantee'){let raw=_commissionServiceItemsV46Base().filter(x=>x.professionalId===p.id&&x.unitId===uid&&x.date>=commissionFrom&&x.date<=commissionTo),comm=raw.reduce((s,x)=>s+Number(x.amount||0),0),min=remunerationFixedValue(r,commissionFrom,commissionTo),diff=Math.max(0,min-comm);if(diff>0)out.push({type:'remuneration',key:`guar:${r.id}:${commissionFrom}:${commissionTo}`,date:commissionTo,unitId:uid,professionalId:p.id,amount:diff,description:'Complemento de garantia',detail:`Garantia ${money(min)} · comissão ${money(comm)} · complemento ${money(diff)}`})}if(['daily','daily_plus'].includes(r.model)){for(const d of (db.professionalDailyWork||[]).filter(d=>d.professionalId===p.id&&d.unitId===uid&&d.date>=commissionFrom&&d.date<=commissionTo))out.push({type:'remuneration',key:`daily:${d.id}`,date:d.date,unitId:uid,professionalId:p.id,amount:Number(d.amount||0),description:'Diária trabalhada',detail:d.note||remModelLabel(r.model)})}}}return out}
const _commissionAllItemsV46Base=commissionAllItems;
commissionAllItems=function(){return [..._commissionAllItemsV46Base(),...remunerationSupplementItems()]}
const _commissionTypeLabelV46=commissionTypeLabel;commissionTypeLabel=function(x){return x.type==='remuneration'?'Remuneração':_commissionTypeLabelV46(x)};
const _commissionTypeClassV46=commissionTypeClass;commissionTypeClass=function(x){return x.type==='remuneration'?'service':_commissionTypeClassV46(x)};

const _renderCommissionCenterV46=renderCommissionCenter;
renderCommissionCenter=function(){_renderCommissionCenterV46();let head=adminPage.querySelector('.page-head');if(head&&!adminPage.querySelector('.v46-rem-actions')){let d=document.createElement('div');d.className='v46-rem-actions';d.style='display:flex;gap:8px;margin-left:8px';d.innerHTML=`<button class="btn btn-soft" onclick="openRemunerationRules('${commissionPro==='all'?'':commissionPro}')">Modelos de remuneração</button><button class="btn btn-ghost" onclick="openDailyWorkForm('${commissionPro==='all'?'':commissionPro}')">+ Diária trabalhada</button>`;head.appendChild(d)}let rows=adminPage.querySelectorAll('.commission-table tbody tr');let ps=commissionCurrentPros();rows.forEach((tr,i)=>{let p=ps[i];if(!p)return;let rule=remunerationRuleFor(p.id,commissionUnit==='all'?(p.units?.[0]||''):commissionUnit,commissionTo);let td=tr.querySelector('td');if(td&&rule&&!td.querySelector('.v46-rem-label'))td.insertAdjacentHTML('beforeend',`<div class="v46-rem-label" style="font-size:10px;color:var(--brand);margin-top:3px">${escapeHtml(remModelLabel(rule.model))}</div>`)})}

// Modelo / Parceria: preço de tabela, valor cobrado, base de comissão e conteúdo ficam separados.
const _commandSettlementV46Base=commandSettlement;
commandSettlement=function(c){let st=_commandSettlementV46Base(c);if(!c?.partnership?.enabled)return st;let gross=Math.max(0,Number(c.partnership.chargedValue||0)),signal=c.useSignal?Math.min(commandLinkedSignal(c),gross):0,creditAvail=clientGeneralCreditBalance(c.clientId),credit=Math.min(Math.max(0,Number(c.creditToUse||0)),creditAvail,Math.max(0,gross-signal)),fee=Math.max(0,Number(c.customerFee||0)),due=Math.max(0,gross-signal-credit+fee);return{...st,gross,signal,credit,fee,due}}
function openModelPartnership(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(!c)return;normalizeCommand(c);let p=c.partnership||{enabled:false,chargedValue:commandGrossTotal(c),commissionBaseMode:'full',customCommissionBase:commandGrossTotal(c),contentRequired:'',contentStatus:'Pendente',contentDueDate:'',note:''},list=commandGrossTotal(c);modal('Modelo / Parceria',`<div class="inline-note"><b>Não é desconto comum.</b> Mantemos separados preço de tabela, valor efetivamente cobrado e base de comissão. A diferença não vira despesa de marketing no DRE; fica identificada como condição comercial de Modelo/Parceria.</div><div class="form-grid" style="margin-top:12px"><div class="field full"><label class="check"><input id="mpEnabled" type="checkbox" ${p.enabled?'checked':''}> Este atendimento é Modelo / Parceria</label></div><div class="field"><label>Preço de tabela da visita</label><input value="${list.toFixed(2)}" disabled></div><div class="field"><label>Valor que a modelo paga</label><input id="mpCharged" type="number" min="0" step="0.01" value="${Number(p.chargedValue??list)}"></div><div class="field"><label>Base da comissão</label><select id="mpCommissionMode"><option value="full" ${p.commissionBaseMode==='full'?'selected':''}>Valor cheio / tabela</option><option value="charged" ${p.commissionBaseMode==='charged'?'selected':''}>Valor efetivamente cobrado</option><option value="custom" ${p.commissionBaseMode==='custom'?'selected':''}>Valor personalizado</option></select></div><div class="field"><label>Base personalizada</label><input id="mpCommissionCustom" type="number" min="0" step="0.01" value="${Number(p.customCommissionBase||list)}"></div><div class="field full"><label>Conteúdo combinado</label><textarea id="mpContent" rows="3" placeholder="Ex.: 1 Reel + 3 Stories + fotos do resultado">${escapeHtml(p.contentRequired||'')}</textarea></div><div class="field"><label>Status do conteúdo</label><select id="mpContentStatus"><option ${p.contentStatus==='Pendente'?'selected':''}>Pendente</option><option ${p.contentStatus==='Parcial'?'selected':''}>Parcial</option><option ${p.contentStatus==='Entregue'?'selected':''}>Entregue</option><option ${p.contentStatus==='Dispensado'?'selected':''}>Dispensado</option></select></div><div class="field"><label>Prazo do conteúdo</label><input id="mpContentDue" type="date" value="${p.contentDueDate||''}"></div><div class="field full"><label>Observação</label><input id="mpNote" value="${escapeAttr(p.note||'')}"></div></div>`,`<button class="btn btn-ghost" onclick="closeModal();openCommand('${cmdId}')">Voltar</button><button class="btn btn-primary" onclick="saveModelPartnership('${cmdId}')">Salvar parceria</button>`)}
function saveModelPartnership(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(!c)return;let enabled=!!document.getElementById('mpEnabled')?.checked;c.partnership={enabled,chargedValue:Math.max(0,Number(document.getElementById('mpCharged')?.value||0)),commissionBaseMode:document.getElementById('mpCommissionMode')?.value||'full',customCommissionBase:Math.max(0,Number(document.getElementById('mpCommissionCustom')?.value||0)),contentRequired:document.getElementById('mpContent')?.value.trim()||'',contentStatus:document.getElementById('mpContentStatus')?.value||'Pendente',contentDueDate:document.getElementById('mpContentDue')?.value||'',note:document.getElementById('mpNote')?.value.trim()||'',updatedAt:new Date().toISOString(),updatedBy:currentUserName()};c.commercialType=enabled?'Modelo/Parceria':'Normal';save();closeModal();openCommand(cmdId);toast(enabled?'Modelo/Parceria aplicado ✓':'Atendimento voltou ao padrão normal')}
const _renderCommandModalV46=renderCommandModal;
renderCommandModal=function(id){_renderCommandModalV46(id);setTimeout(()=>{let c=db.clientCommands.find(x=>x.id===id),m=document.querySelector('#modalHost .modal');if(!c||!m)return;let anchor=m.querySelector('.command-sync-note')||m.querySelector('.inline-note');if(!anchor||m.querySelector('.v46-partnership-card'))return;let p=c.partnership||{},html=`<div class="v46-partnership-card" style="border:1px solid #e4d8e7;border-radius:12px;padding:11px 12px;margin:10px 0;background:#fcf9fd;display:flex;gap:12px;align-items:center"><div style="flex:1"><b>${p.enabled?'Modelo / Parceria':'Atendimento normal'}</b><div class="muted" style="font-size:11px;margin-top:3px">${p.enabled?`Tabela ${money(commandGrossTotal(c))} · cobrado ${money(p.chargedValue||0)} · conteúdo ${escapeHtml(p.contentStatus||'Pendente')}`:'Use quando a cliente modelo paga parte ou nada e entrega conteúdo para o salão.'}</div></div><button class="btn btn-soft btn-sm" onclick="closeModal();openModelPartnership('${id}')">${p.enabled?'Editar parceria':'Configurar parceria'}</button></div>`;anchor.insertAdjacentHTML('afterend',html)},0)}

// Conta mensal / faturar cliente
const _paymentNeedsAccountV46=paymentNeedsAccount;
paymentNeedsAccount=function(methodId){if(methodId==='pm_monthly')return false;return _paymentNeedsAccountV46(methodId)};
const _financeActiveConfigMethodsV46=financeActiveConfigMethods;
financeActiveConfigMethods=function(){return _financeActiveConfigMethodsV46().filter(m=>m.id!=='pm_monthly')};
function clientOpenReceivables(clientId){return (db.clientReceivables||[]).filter(r=>r.clientId===clientId&&Number(r.balance||0)>.009).sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function clientReceivableBalance(clientId){return clientOpenReceivables(clientId).reduce((s,r)=>s+Number(r.balance||0),0)}
function defaultMonthlyDue(clientId,baseDate){let c=db.clients.find(x=>x.id===clientId),d=new Date((baseDate||localDateISO())+'T12:00:00'),day=Math.max(1,Math.min(28,Number(c?.monthlyBillingDay||28)));d.setMonth(d.getMonth()+1,day);return localDateISO(d)}
const _paymentLineHtmlV46=paymentLineHtml;
paymentLineHtml=function(c,p,i){if(p.methodId!=='pm_monthly')return _paymentLineHtmlV46(c,p,i);return `<div class="payment-line" data-pay-index="${i}"><div class="field"><label>Forma de pagamento</label><select class="pay-method" onchange="paymentMethodChanged('${c.id}',${i},this.value)">${paymentMethodOptions(p.methodId)}</select></div><div class="field"><label>Vencimento</label><input class="pay-due-date" type="date" value="${p.dueDate||defaultMonthlyDue(c.clientId,c.date)}"></div><div class="field"><label>Valor para conta mensal</label><input class="pay-amount" type="number" min="0" step="0.01" value="${Number(p.amount||0)}" oninput="paymentRefreshTotals('${c.id}')"></div><button class="btn btn-danger btn-sm" title="Remover" onclick="paymentRemoveLine('${c.id}',${i})">×</button></div>`}
const _paymentReadDraftV46=paymentReadDraft;
paymentReadDraft=function(c){_paymentReadDraftV46(c);document.querySelectorAll('[data-pay-index]').forEach(row=>{let i=Number(row.dataset.payIndex),p=c.paymentDraft?.[i];if(p?.methodId==='pm_monthly')p.dueDate=row.querySelector('.pay-due-date')?.value||defaultMonthlyDue(c.clientId,c.date)});save()}
const _finalizeCommandPaymentV46=finalizeCommandPayment;
finalizeCommandPayment=function(cmdId){let c=db.clientCommands.find(x=>x.id===cmdId);if(!c)return;try{paymentReadDraft(c)}catch(e){}let original=structuredClone(c.paymentDraft||[]),monthly=original.filter(p=>p.methodId==='pm_monthly'&&Number(p.amount)>0),cli=db.clients.find(x=>x.id===c.clientId);if(monthly.length&&!cli?.monthlyBillingEnabled){toast('Esta cliente ainda não está habilitada para Conta mensal. Ative na ficha da cliente.');return}let before=c.status;if(monthly.length){c.paymentDraft=(c.paymentDraft||[]).map(p=>p.methodId==='pm_monthly'?{...p,methodId:'pm_barter',accountId:''}:p)}_finalizeCommandPaymentV46(cmdId);c=db.clientCommands.find(x=>x.id===cmdId);if(monthly.length&&c&&before!=='Pago'&&c.status==='Pago'){let now=new Date();monthly.forEach((p,idx)=>db.clientReceivables.push({id:'recv'+Date.now()+'_'+idx,clientId:c.clientId,clientName:cli?.name||c.clientName||'',commandId:c.id,unitId:c.unitId,date:c.date,dueDate:p.dueDate||defaultMonthlyDue(c.clientId,c.date),originalAmount:Number(p.amount||0),balance:Number(p.amount||0),status:'Em aberto',createdAt:now.toISOString(),createdBy:currentUserName()}));c.receivableOpen=true;c.receivableStatus='Em aberto';c.paymentRecords=original.map(p=>({id:p.id||('pr'+Date.now()+Math.random()),methodId:p.methodId,amount:Number(p.amount||0),accountId:p.accountId||'',processorFee:Number(p.processorFee||0),professionalId:p.professionalId||'',directChannel:p.directChannel||'',dueDate:p.dueDate||''}));c.payments=(c.payments||[]).filter(x=>!/^Permuta/.test(x));monthly.forEach(p=>c.payments.push(`Conta mensal • ${money(p.amount)} · vence ${formatDateBR(p.dueDate||defaultMonthlyDue(c.clientId,c.date))}`));save();toast(`Comanda concluída · ${money(monthly.reduce((s,p)=>s+Number(p.amount||0),0))} lançados na conta mensal da cliente ✓`)}}

const _openClientV46=openClient;
openClient=function(id,tab='resumo'){_openClientV46(id,tab==='conta_mensal'?'resumo':tab);setTimeout(()=>{let tabs=document.querySelector('#modalHost .client-tabs');if(tabs&&!tabs.querySelector('[data-client-tab="conta_mensal"]')){let hist=tabs.querySelector('[data-client-tab="historico"]');let btn=document.createElement('button');btn.dataset.clientTab='conta_mensal';btn.textContent='Conta mensal';btn.onclick=()=>switchClientProfileTab('conta_mensal');tabs.insertBefore(btn,hist||null)}if(tab==='conta_mensal')switchClientProfileTab('conta_mensal')},0)}
const _renderClientProfileTabV46=renderClientProfileTab;
renderClientProfileTab=function(tab){if(tab!=='conta_mensal')return _renderClientProfileTabV46(tab);let id=window.clientProfileId,c=db.clients.find(x=>x.id===id),out=document.getElementById('clientTabContent');if(!c||!out)return;let rec=clientOpenReceivables(id),bal=clientReceivableBalance(id);out.innerHTML=`<div class="client-balance"><div><b>Conta mensal</b><div class="muted">Serviços consumidos agora e pagos posteriormente.</div></div><div style="text-align:right"><div class="muted">Saldo a receber</div><strong>${money(bal)}</strong></div></div><div class="client-section"><h3>Configuração</h3><div class="form-grid"><div class="field"><label class="check"><input id="cmEnabled" type="checkbox" ${c.monthlyBillingEnabled?'checked':''}> Habilitar conta mensal para esta cliente</label></div><div class="field"><label>Limite de crédito</label><input id="cmLimit" type="number" min="0" step="0.01" value="${Number(c.monthlyCreditLimit||0)}"></div><div class="field"><label>Dia padrão de vencimento</label><input id="cmDay" type="number" min="1" max="28" value="${Number(c.monthlyBillingDay||28)}"></div><div class="field" style="display:flex;align-items:end"><button class="btn btn-soft" onclick="saveClientMonthlySettings('${id}')">Salvar configuração</button></div></div></div><div class="client-section"><div style="display:flex;align-items:center;gap:10px"><div><h3 style="margin:0">Valores em aberto</h3><div class="muted">Cada comanda permanece rastreável por data e unidade.</div></div><div class="spacer"></div><button class="btn btn-primary" ${bal>0?'':'disabled'} onclick="openClientMonthlySettlement('${id}')">Receber conta</button></div><div class="client-table-wrap" style="margin-top:10px"><table class="client-table"><thead><tr><th>Data</th><th>Comanda</th><th>Unidade</th><th>Vencimento</th><th>Original</th><th>Saldo</th><th>Status</th></tr></thead><tbody>${rec.map(r=>`<tr><td>${formatDateBR(r.date)}</td><td>#${escapeHtml(String(r.commandId||'').replace(/\D/g,''))}</td><td>${escapeHtml(financeUnitLabel(r.unitId))}</td><td>${formatDateBR(r.dueDate)}</td><td>${money(r.originalAmount)}</td><td><b>${money(r.balance)}</b></td><td><span class="pill">${r.balance<r.originalAmount?'Parcial':'Em aberto'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="client-empty">Nenhum valor em aberto.</td></tr>'}</tbody></table></div></div>`}
function saveClientMonthlySettings(id){let c=db.clients.find(x=>x.id===id);if(!c)return;c.monthlyBillingEnabled=!!document.getElementById('cmEnabled')?.checked;c.monthlyCreditLimit=Math.max(0,Number(document.getElementById('cmLimit')?.value||0));c.monthlyBillingDay=Math.max(1,Math.min(28,Number(document.getElementById('cmDay')?.value||28)));save();toast('Configuração da conta mensal salva ✓')}
function monthlySettlementAccountOptions(methodId){return (db.financialAccounts||[]).filter(a=>a.active!==false&&(a.paymentMethodIds||[]).includes(methodId)).map(a=>`<option value="${a.id}">${escapeHtml(a.name)}</option>`).join('')}
function monthlySettlementMethodChanged(){let m=document.getElementById('cmPayMethod')?.value,sel=document.getElementById('cmPayAccount');if(sel)sel.innerHTML=monthlySettlementAccountOptions(m)}
function openClientMonthlySettlement(id){let c=db.clients.find(x=>x.id===id),rec=clientOpenReceivables(id),bal=clientReceivableBalance(id);if(!c||!rec.length)return;let method='pm_pix';modal(`Receber conta mensal · ${c.name}`,`<div class="inline-note"><b>Saldo em aberto:</b> ${money(bal)}<br>O pagamento será alocado das comandas mais antigas para as mais novas. Pode ser parcial.</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Data do recebimento</label><input id="cmPayDate" type="date" value="${localDateISO()}"></div><div class="field"><label>Forma de pagamento</label><select id="cmPayMethod" onchange="monthlySettlementMethodChanged()">${(db.paymentMethods||[]).filter(m=>!['pm_direct','pm_barter','pm_monthly'].includes(m.id)&&m.active!==false).map(m=>`<option value="${m.id}" ${m.id===method?'selected':''}>${escapeHtml(m.name)}</option>`).join('')}</select></div><div class="field full"><label>Conta / destino</label><select id="cmPayAccount">${monthlySettlementAccountOptions(method)}</select></div><div class="field full"><label>Valor recebido agora</label><input id="cmPayAmount" type="number" min="0.01" max="${bal}" step="0.01" value="${bal.toFixed(2)}"></div><div class="field full"><label>Observação</label><input id="cmPayNote" placeholder="Ex.: acerto mensal de setembro"></div></div>`,`<button class="btn btn-ghost" onclick="closeModal();openClient('${id}','conta_mensal')">Voltar</button><button class="btn btn-primary" onclick="saveClientMonthlySettlement('${id}')">Confirmar recebimento</button>`)}
function saveClientMonthlySettlement(id){let c=db.clients.find(x=>x.id===id),rec=clientOpenReceivables(id),bal=roundMoney(clientReceivableBalance(id)),amount=roundMoney(Math.max(0,Number(document.getElementById('cmPayAmount')?.value||0)));if(!c||!(amount>0)||amount>bal+.009){toast('Informe um valor válido até o saldo em aberto');return}let date=document.getElementById('cmPayDate')?.value||localDateISO(),methodId=document.getElementById('cmPayMethod')?.value||'pm_pix',accountId=document.getElementById('cmPayAccount')?.value||'',acc=db.financialAccounts.find(a=>a.id===accountId),method=db.paymentMethods.find(m=>m.id===methodId);if(!acc){toast('Selecione a conta de destino');return}let left=amount,alloc=[];for(const r of rec){if(left<=.009)break;let use=roundMoney(Math.min(left,Number(r.balance||0)));r.balance=roundMoney(Math.max(0,Number(r.balance||0)-use));r.status=r.balance<=.009?'Quitado':'Parcial';left-=use;alloc.push({receivableId:r.id,commandId:r.commandId,unitId:r.unitId,amount:use});if(r.balance<=.009){let cmd=db.clientCommands.find(x=>x.id===r.commandId);if(cmd&&!clientOpenReceivables(id).some(z=>z.commandId===cmd.id&&z.id!==r.id))cmd.receivableOpen=false}}
 let fee=paymentProcessorFee(methodId,accountId,amount);db.clientReceivablePayments.push({id:'crp'+Date.now(),clientId:id,date,amount,methodId,paymentMethod:method?.name||'',accountId,accountName:acc?.name||'',allocations:alloc,note:document.getElementById('cmPayNote')?.value.trim()||'',createdAt:new Date().toISOString(),createdBy:currentUserName()});for(const a of alloc){db.demoCashMovements.push({id:'cm_month'+Date.now()+Math.random(),clientId:id,unitId:a.unitId,amount:a.amount,paymentMethod:method?.name||'',account:acc?.name||'',type:'Recebimento conta mensal',date,createdAt:new Date().toISOString(),user:currentUserName(),processorFee:fee*(a.amount/amount)});db.demoFinancialEntries.push({id:'fe_month'+Date.now()+Math.random(),clientId:id,unitId:a.unitId,amount:a.amount,nature:'Recebimento de conta mensal',category:'Contas a receber',account:acc?.name||'',date,origin:`Acerto conta mensal · ${c.name}`,processorFee:fee*(a.amount/amount),dreImpact:false})}save();closeModal();openClient(id,'conta_mensal');toast(amount+0.009<bal?'Pagamento parcial registrado · saldo mantido ✓':'Conta mensal quitada ✓')}


